class Solution:
    def minSplitMerge(self, nums1: List[int], nums2: List[int]) -> int:
        from collections import deque
        start, target = tuple(nums1), tuple(nums2)
        if start == target:
            return 0
        n = len(start)
        q = deque([start])
        dist = {start: 0}
        while q:
            cur = q.popleft()
            d = dist[cur]
            lst = list(cur)
            for L in range(n):
                for R in range(L, n):
                    mid = lst[L:R+1]
                    rest = lst[:L] + lst[R+1:]
                    for p in range(len(rest) + 1):
                        nt = tuple(rest[:p] + mid + rest[p:])
                        if nt == target:
                            return d + 1
                        if nt not in dist:
                            dist[nt] = d + 1
                            q.append(nt)
        return -1

