class Solution {
public:
    int minSplitMerge(vector<int>& nums1, vector<int>& nums2) {
        vector<int> start = nums1, target = nums2;
        if (start == target) return 0;
        int n = start.size();
        queue<vector<int>> q;
        map<vector<int>, int> dist;
        q.push(start); dist[start] = 0;
        while (!q.empty()) {
            auto cur = q.front(); q.pop();
            int d = dist[cur];
            for (int L = 0; L < n; L++)
                for (int R = L; R < n; R++) {
                    vector<int> mid(cur.begin() + L, cur.begin() + R + 1);
                    vector<int> rest = cur;
                    rest.erase(rest.begin() + L, rest.begin() + R + 1);
                    for (int p = 0; p <= (int)rest.size(); p++) {
                        vector<int> nt = rest;
                        nt.insert(nt.begin() + p, mid.begin(), mid.end());
                        if (nt == target) return d + 1;
                        if (!dist.count(nt)) { dist[nt] = d + 1; q.push(nt); }
                    }
                }
        }
        return -1;
    }
};

