class Solution {
    public int minSplitMerge(int[] nums1, int[] nums2) {
        int n = nums1.length;
        String start = Arrays.toString(nums1), target = Arrays.toString(nums2);
        if (start.equals(target)) return 0;
        Deque<int[]> q = new ArrayDeque<>();
        Map<String, Integer> dist = new HashMap<>();
        q.add(nums1.clone()); dist.put(start, 0);
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int d = dist.get(Arrays.toString(cur));
            for (int L = 0; L < n; L++)
                for (int R = L; R < n; R++) {
                    int[] mid = Arrays.copyOfRange(cur, L, R + 1);
                    int[] rest = new int[n - (R - L + 1)];
                    int t = 0;
                    for (int i = 0; i < n; i++) if (i < L || i > R) rest[t++] = cur[i];
                    for (int p = 0; p <= rest.length; p++) {
                        int[] nt = new int[n];
                        System.arraycopy(rest, 0, nt, 0, p);
                        System.arraycopy(mid, 0, nt, p, mid.length);
                        System.arraycopy(rest, p, nt, p + mid.length, rest.length - p);
                        String key = Arrays.toString(nt);
                        if (key.equals(target)) return d + 1;
                        if (!dist.containsKey(key)) { dist.put(key, d + 1); q.add(nt); }
                    }
                }
        }
        return -1;
    }
}

