var minSplitMerge = function(nums1, nums2) {
    const key = a => a.join(',');
    const start = key(nums1), target = key(nums2);
    if (start === target) return 0;
    const n = nums1.length;
    const q = [nums1.slice()], dist = new Map([[start, 0]]);
    while (q.length) {
        const cur = q.shift(), d = dist.get(key(cur));
        for (let L = 0; L < n; L++)
            for (let R = L; R < n; R++) {
                const mid = cur.slice(L, R + 1);
                const rest = cur.slice(0, L).concat(cur.slice(R + 1));
                for (let p = 0; p <= rest.length; p++) {
                    const nt = rest.slice(0, p).concat(mid, rest.slice(p));
                    const k = key(nt);
                    if (k === target) return d + 1;
                    if (!dist.has(k)) { dist.set(k, d + 1); q.push(nt); }
                }
            }
    }
    return -1;
};
